//! Canonical transaction construction for A-TownChain.
use atc_blockchain::{crypto::signing_bytes,mempool::{Transaction,TxType}};
use ed25519_dalek::{Signer,SigningKey};
pub struct TransactionBuilder{pub chain_id:u64,pub tx_type:TxType,pub sender:String,pub recipient:Option<String>,pub amount:u64,pub gas_price:u64,pub gas_limit:u64,pub nonce:u64,pub timestamp:u64,pub payload:Vec<u8>,pub poh_hash:[u8;32]}
impl TransactionBuilder{pub fn transfer(chain_id:u64,sender:impl Into<String>,recipient:impl Into<String>,amount:u64,gas_price:u64,gas_limit:u64,nonce:u64,timestamp:u64)->Self{Self{chain_id,tx_type:TxType::Transfer,sender:sender.into(),recipient:Some(recipient.into()),amount,gas_price,gas_limit,nonce,timestamp,payload:Vec::new(),poh_hash:[0;32]}}pub fn payload(mut self,p:Vec<u8>)->Self{self.payload=p;self}pub fn poh_hash(mut self,h:[u8;32])->Self{self.poh_hash=h;self}pub fn sign(self,key:&SigningKey)->Transaction{let mut tx=Transaction::new_with_chain_id(self.chain_id,self.tx_type,self.sender,self.recipient,self.amount,self.gas_price,self.gas_limit,self.nonce,self.timestamp,self.payload,[0;64],key.verifying_key().to_bytes(),self.poh_hash);tx.signature=key.sign(&signing_bytes(&tx)).to_bytes();tx}}
#[cfg(test)]mod tests{use super::*;#[test]fn canonical_signature_is_accepted(){let key=SigningKey::from_bytes(&[9u8;32]);let tx=TransactionBuilder::transfer(658467,"alice","bob",10,1,1000,0,1).sign(&key);assert_eq!(tx.chain_id,658467);assert_eq!(tx.signature.len(),64);assert_ne!(tx.id,[0;32]);}}
